/**
 * Money helpers. All amounts are integer cents; this helper rounds a fractional
 * cent amount to the nearest integer cent, halves up (towards +infinity).
 */
export function roundHalfUpCents(x) {
  return Math.floor(x + 0.5)
}

import { roundHalfUpCents } from './money.js'

/**
 * Price cart lines: gross per line, the 10% bulk discount for qty >= 10
 * (rounded once per line), and the discounted subtotal.
 */
export function priceLines(lines) {
  const priced = lines.map((line) => {
    const lineGross = line.unitPriceCents * line.qty
    const lineDiscount = line.qty >= 10 ? roundHalfUpCents((lineGross * 10) / 100) : 0
    const lineNet = lineGross - lineDiscount
    return { id: line.id, lineGross, lineDiscount, lineNet }
  })
  const discountedSubtotal = priced.reduce((sum, line) => sum + line.lineNet, 0)
  return { lines: priced, discountedSubtotal }
}

import { roundHalfUpCents } from './money.js'

/**
 * Apply a percent coupon to a priced cart. Per the README, the coupon discount
 * is computed exactly once on the whole discounted subtotal.
 */
export function applyCoupon(priced, ratePercent) {
  if (ratePercent === null) {
    return { couponDiscount: 0, amountAfterCoupon: priced.discountedSubtotal }
  }
  const couponDiscount = priced.lines.reduce(
    (sum, line) => sum + roundHalfUpCents((line.lineNet * ratePercent) / 100),
    0,
  )
  return { couponDiscount, amountAfterCoupon: priced.discountedSubtotal - couponDiscount }
}

import { roundHalfUpCents } from './money.js'

/** Apply 8% tax to the post-coupon amount. Tax is rounded exactly once. */
export function applyTax(amountAfterCoupon) {
  const tax = roundHalfUpCents((amountAfterCoupon * 8) / 100)
  return { tax, amountWithTax: amountAfterCoupon + tax }
}

import { priceLines } from './pricing.js'
import { applyCoupon } from './coupons.js'
import { applyTax } from './tax.js'

/** Full checkout pipeline: price lines, apply the coupon, then apply tax. */
export function checkoutTotal(lines, couponRatePercent) {
  const priced = priceLines(lines)
  const { couponDiscount, amountAfterCoupon } = applyCoupon(priced, couponRatePercent)
  const { tax } = applyTax(amountAfterCoupon)
  return {
    discountedSubtotal: priced.discountedSubtotal,
    couponDiscount,
    tax,
    total: amountAfterCoupon + tax,
  }
}

