import { test } from 'node:test'
import assert from 'node:assert/strict'
import { roundHalfUpCents } from '../src/money.js'

test('money: rounds half up', () => {
  assert.equal(roundHalfUpCents(2.5), 3)
  assert.equal(roundHalfUpCents(52.5), 53)
})

test('money: rounds down below half', () => {
  assert.equal(roundHalfUpCents(2.4), 2)
  assert.equal(roundHalfUpCents(857.01), 857)
  assert.equal(roundHalfUpCents(910.88), 911)
})

test('money: zero stays zero', () => {
  assert.equal(roundHalfUpCents(0), 0)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { priceLines } from '../src/pricing.js'

test('pricing: bulk discount starts at qty 10', () => {
  const priced = priceLines([{ id: 'b', unitPriceCents: 100, qty: 10 }])
  assert.deepEqual(priced.lines, [{ id: 'b', lineGross: 1000, lineDiscount: 100, lineNet: 900 }])
  assert.equal(priced.discountedSubtotal, 900)
})

test('pricing: no bulk discount below qty 10', () => {
  const priced = priceLines([{ id: 'a', unitPriceCents: 100, qty: 9 }])
  assert.deepEqual(priced.lines, [{ id: 'a', lineGross: 900, lineDiscount: 0, lineNet: 900 }])
  assert.equal(priced.discountedSubtotal, 900)
})

test('pricing: discounted subtotal sums line nets', () => {
  const priced = priceLines([
    { id: 'a', unitPriceCents: 250, qty: 3 },
    { id: 'b', unitPriceCents: 1200, qty: 10 },
    { id: 'c', unitPriceCents: 99, qty: 7 },
  ])
  assert.equal(priced.discountedSubtotal, 750 + 10800 + 693)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { priceLines } from '../src/pricing.js'
import { applyCoupon } from '../src/coupons.js'

test('coupons: discount is rounded once on the whole discounted subtotal, never per line', () => {
  // Line nets 750 and 1010. Whole-subtotal rule: round(1760 * 7 / 100) = round(123.2) = 123.
  // A per-line implementation would compute round(52.5) + round(70.7) = 53 + 71 = 124.
  const priced = priceLines([
    { id: 'a', unitPriceCents: 250, qty: 3 },
    { id: 'b', unitPriceCents: 202, qty: 5 },
  ])
  assert.equal(priced.discountedSubtotal, 1760)
  const { couponDiscount } = applyCoupon(priced, 7)
  assert.equal(couponDiscount, 123)
})

test('coupons: null rate means no discount', () => {
  const priced = priceLines([{ id: 'a', unitPriceCents: 500, qty: 2 }])
  const result = applyCoupon(priced, null)
  assert.equal(result.couponDiscount, 0)
  assert.equal(result.amountAfterCoupon, 1000)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { checkoutTotal } from '../src/checkout.js'

const CART = [
  { id: 'a', unitPriceCents: 250, qty: 3 },
  { id: 'b', unitPriceCents: 1200, qty: 10 },
  { id: 'c', unitPriceCents: 99, qty: 7 },
]

test('checkout: multi-line cart with 7% coupon totals exactly per spec', () => {
  // Spec pipeline: subtotal 12243; coupon round(12243*7/100)=857 (once, whole cart);
  // tax round((12243-857)*8/100)=round(910.88)=911; total 12297.
  // A per-line coupon rounding (or any other single-rounding violation) lands on 12296.
  const result = checkoutTotal(CART, 7)
  assert.equal(result.discountedSubtotal, 12243)
  assert.equal(result.couponDiscount, 857)
  assert.equal(result.tax, 911)
  assert.equal(result.total, 12297)
})

test('checkout: tax applies after coupon discount', () => {
  // gross 10000, coupon 10% -> 1000; tax on 9000 = 720; total 9720.
  // Tax-before-coupon would give tax 800 and total 9800.
  const result = checkoutTotal([{ id: 'x', unitPriceCents: 10000, qty: 1 }], 10)
  assert.equal(result.couponDiscount, 1000)
  assert.equal(result.tax, 720)
  assert.equal(result.total, 9720)
})

test('checkout: cart without coupon', () => {
  const result = checkoutTotal([{ id: 'x', unitPriceCents: 333, qty: 2 }], null)
  assert.equal(result.discountedSubtotal, 666)
  assert.equal(result.couponDiscount, 0)
  assert.equal(result.tax, 53)
  assert.equal(result.total, 719)
})

test('checkout: empty cart totals zero', () => {
  const result = checkoutTotal([], null)
  assert.equal(result.total, 0)
})

